CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL);
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE sites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, name text NOT NULL, UNIQUE(organization_id,name));
CREATE TABLE site_access (site_id uuid REFERENCES sites, user_id uuid REFERENCES users, role text NOT NULL CHECK(role IN ('ADMIN','EDITOR','VIEWER')), PRIMARY KEY(site_id,user_id));
CREATE TABLE committees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES sites, name text NOT NULL, valid_from date NOT NULL, valid_until date, CHECK(valid_until IS NULL OR valid_until >= valid_from));
CREATE TABLE members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), committee_id uuid NOT NULL REFERENCES committees, name text NOT NULL, representation text NOT NULL CHECK(representation IN ('WORKER','EMPLOYER')), participation text NOT NULL CHECK(participation IN ('PRINCIPAL','ALTERNATE','ADVISER')), valid_from date NOT NULL, valid_until date);
CREATE TABLE inspections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES sites, title text NOT NULL, area text NOT NULL, inspected_on date NOT NULL, inspector_id uuid NOT NULL REFERENCES users, status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','IN_PROGRESS','COMPLETED')), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), inspection_id uuid NOT NULL REFERENCES inspections, description text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), finding_id uuid NOT NULL REFERENCES findings, title text NOT NULL, owner_id uuid NOT NULL REFERENCES users, due_on date NOT NULL, priority text NOT NULL CHECK(priority IN ('HIGH','MEDIUM','LOW')), status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','IN_PROGRESS','PENDING_VERIFICATION','CLOSED')), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_id uuid NOT NULL REFERENCES actions, author_id uuid NOT NULL REFERENCES users, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_id uuid NOT NULL REFERENCES actions, verifier_id uuid NOT NULL REFERENCES users, approved boolean NOT NULL, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, site_id uuid NOT NULL REFERENCES sites, actor_id uuid NOT NULL REFERENCES users, entity_id uuid NOT NULL, event text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX inspections_site_date ON inspections(site_id,inspected_on DESC);
CREATE INDEX findings_inspection ON findings(inspection_id);
CREATE INDEX actions_finding ON actions(finding_id);
CREATE INDEX actions_owner_due ON actions(owner_id,due_on);
CREATE INDEX evidence_action ON evidence(action_id);
CREATE INDEX audit_site_created ON audit_events(site_id,created_at DESC);
CREATE INDEX access_user ON site_access(user_id);
